create table notes (created_at date not null, home_id bigint not null, id bigint generated by default as identity, writer_id bigint not null, content TEXT, title varchar(255) not null, primary key (id));
alter table if exists notes add constraint fk_notes_home foreign key (home_id) references homes;
alter table if exists notes add constraint fk_notes_writer foreign key (writer_id) references users;